def sum_even_numbers(numbers):
    total = 0
    for value in numbers:
        if value % 2 == 0:
            total += value
    return total

def rotate_right(items, k):
    if not items:
        return []
    shift = k % len(items)
    cut = len(items) - shift
    return items[cut:] + items[:cut]

def window_sum(values, start, length):
    low = max(0, start)
    high = min(len(values), start + length)
    if high <= low:
        return 0
    total = 0
    for i in range(low, high):
        total += values[i]
    return total

def max_subarray_sum(numbers):
    if not numbers:
        return 0
    best = numbers[0]
    current = numbers[0]
    for value in numbers[1:]:
        if current + value > value:
            current = current + value
        else:
            current = value
        if current > best:
            best = current
    return best

def most_frequent_word(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    best = ""
    best_count = 0
    for word in words:
        if counts[word] > best_count:
            best = word
            best_count = counts[word]
    return best

def reverse_word_order(sentence):
    words = sentence.split()
    reversed_words = []
    for i in range(len(words) - 1, -1, -1):
        reversed_words.append(words[i])
    return " ".join(reversed_words)

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def two_sum(numbers, target):
    seen = {}
    for j in range(len(numbers)):
        need = target - numbers[j]
        if need in seen:
            return [seen[need], j]
        seen[numbers[j]] = j
    return []

def is_clean_palindrome(text):
    cleaned = [ch.lower() for ch in text if ch.isalnum()]
    low = 0
    high = len(cleaned) - 1
    while low < high:
        if cleaned[low] != cleaned[high]:
            return False
        low += 1
        high -= 1
    return True

def is_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0
